#include <iostream>
#include <string>
#include <vector>
using namespace std;

#define rep(i, n) for (int i = 0; i < int(n); i++)

int main() {
  string N;
  cin >> N;
  long long ans = 0;
  for (int s = 1; s <= 9 * 14; s++) {
    vector dp(N.size() + 1, vector(s + 1, vector(s, vector(2, 0LL))));
    dp[0][0][0][1] = 1;
    rep(d, N.size()) rep(i, s + 1) rep(j, s) rep(f, 2) rep(t, 10) {
      if (i + t > s) continue;
      if (f and N[d] - '0' < t) continue;
      dp[d + 1][i + t][(j * 10 + t) % s][f and N[d] - '0' == t] += dp[d][i][j][f];
    }
    ans += dp[N.size()][s][0][0] + dp[N.size()][s][0][1];
  }
  cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#include <atcoder/internal_math>
using namespace atcoder;

// f(n, s, r, m) := n 以下で、桁和が s で、m で割って r あまるものの個数
map<ll, ll> mem[130][130][130];  // mem[s][r][m][n] にメモ
ll f(ll n, int s, int r, int m)
{
  if (n == 0)
    return s == 0 && r == 0;
  if (mem[s][r][m].contains(n))
    return mem[s][r][m][n];
  ll res = 0;
  for (int d = 0; d < 10; d++)
  {
    ll nn = n / 10 - (d > n % 10);
    int ns = s - d;
    if (nn < 0 || ns < 0)
      continue;
    auto [g, x] = internal::inv_gcd(10, m);
    if ((r - d) % g != 0)
      continue;
    int nm = m / g;
    int nr = (((r - d) / g * x) % nm + nm) % nm;
    res += f(nn, ns, nr, nm);
  }
  mem[s][r][m][n] = res;
  return res;
}

int main()
{
  ll N;
  cin >> N;
  ll ans = 0;
  for (int s = 1; s <= 126; s++)
  {
    ans += f(N, s, 0, s);
  }
  cout << ans << endl;
}

#include<bits/stdc++.h>
using namespace std;
#define ll long long

ll N, dp[16][130][130][130][2];
int main() {
    cin >> N;
    // 初期化
    for (int s = 1; s <= 9 * 14; s++) dp[0][s][0][0][0] = 1;

    // 遷移
    ll pow10 = 1;
    for (int d = 0; d < 15; d ++) {
        int n = N % 10;
        for (int s = 1; s <= 9 * 14; s++) {
            for (int i = 0; i <= 9 * 14; i++) {
                for (int j = 0; j < s; j++) {
                    for (int f = 0; f < 2; f++) {
                        for (int t = 0; t < 10; t++) {
                            if (i + t > s) break;
                            int nf = 2 * n < 2 * t + f;
                            dp[d + 1][s][i + t][(pow10 * t + j) % s][nf] += dp[d][s][i][j][f];
                        }
                    }
                }
            }
        }
        N /= 10;
        pow10 *= 10;
    }

    // 答えの計算
    ll ans = 0;
    for (int s = 1; s <= 9 * 14; s++) ans += dp[15][s][s][0][0];
    cout << ans << '\n';
}
